@Injectable()
class Impl {
  n = 0
}
class Token {}
providers: [Impl, { provide: Token, useClass: Impl }]
const a = app.get(Impl)
const b = app.get(Token)
a.n = 1
console.log(b.n)

@Injectable()
class Src {
  n = 1
}
providers: [Src, { provide: 'X', useExisting: Src }]
app.get(Src).n = 7
console.log(app.get('X').n)

@Injectable()
class A {
  constructor(@Inject('B') public b: unknown) {}
}
@Injectable()
class B {
  constructor(@Inject('A') public a: unknown) {}
}
try {
  await Test.createTestingModule({
    providers: [
      { provide: 'A', useClass: A },
      { provide: 'B', useClass: B },
    ],
  }).compile()
  console.log(1)
} catch {
  console.log(0)
}

@Injectable()
class S {
  n = 4
}
@Injectable()
class Box {
  constructor(private ref: ModuleRef) {}
  read() {
    return this.ref.get(S).n
  }
}
console.log(app.get(Box).read())

@Module({})
class Dyn {
  static register(n: number) {
    return {
      module: Dyn,
      providers: [{ provide: 'CFG', useValue: n }],
      exports: ['CFG'],
    }
  }
}
@Module({ imports: [Dyn.register(3)] })
class App {}
console.log(app.get('CFG'))

@Injectable()
class S {
  n() {
    return 1
  }
}
const app = await Test.createTestingModule({ providers: [S] })
  .overrideProvider(S)
  .useValue({ n: () => 8 })
  .compile()
console.log(app.get(S).n())

@Injectable()
class L implements OnModuleInit, OnApplicationBootstrap {
  onModuleInit() {
    console.log(1)
  }
  onApplicationBootstrap() {
    console.log(2)
  }
}
await app.init()

@Injectable()
class Dep {
  n = 2
}
providers: [
  Dep,
  {
    provide: 'N',
    inject: [Dep],
    useFactory: (d: Dep) => d.n * 4,
  },
]
console.log(app.get('N'))

@Injectable()
class Only {
  n = 3
}
@Module({ providers: [Only], exports: [Only] })
class Inner {}
@Module({ imports: [Inner] })
class Root {}
console.log(app.select(Inner).get(Only).n)

@Injectable()
class S {
  n() {
    return 1
  }
}
@Injectable()
class Fake {
  n() {
    return 9
  }
}
const app = await Test.createTestingModule({ providers: [S] })
  .overrideProvider(S)
  .useClass(Fake)
  .compile()
console.log(app.get(S).n())

@Injectable()
class A {
  n = 2
}
providers: [A, { provide: 'B', useExisting: A }, { provide: 'C', useExisting: 'B' }]
app.get(A).n = 4
console.log(app.get('C').n)

let n = 0
providers: [{
  provide: 'N',
  useFactory: () => {
    n += 1
    return n
  },
}]
console.log(app.get('N'))
console.log(app.get('N'))
